package com.asmj.marketplace.service.model;
import lombok.*;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;import java.time.*;import java.util.*;
@Data @Builder @NoArgsConstructor @AllArgsConstructor @Document("service_bookings") public class ServiceBooking{@Id String id;@Indexed(unique=true) String bookingNumber;@Indexed String serviceId;@Indexed String vendorId;@Indexed String customerId;String serviceName,packageId,packageName;LocalDate serviceDate;LocalTime startTime,endTime;String customerName,customerMobile,address,city,state,pincode,landmark,notes,status;double baseAmount,taxAmount,discountAmount,totalAmount,commissionAmount,cancellationFeeAmount,refundAmount;String discountCode;List<StatusEntry> statusHistory;List<ProviderNote> completionNotes;Instant createdAt,updatedAt;@Data @Builder @NoArgsConstructor @AllArgsConstructor public static class StatusEntry{String status,actorId,note;Instant at;}@Data @Builder @NoArgsConstructor @AllArgsConstructor public static class ProviderNote{String text,proofUrl,actorId;Instant at;}}
